package br.pucrio.inf1416.cofre.auth;

import br.pucrio.inf1416.cofre.db.Group;
import java.util.Arrays;

/** Owns copies; never put a credential-bearing value in a record's autogenerated toString. */
public final class RegistrationRequest implements AutoCloseable {
    final String certificatePath;
    final String keyPath;
    final Group group;
    final char[] passphrase;
    final char[] password;
    final char[] confirmation;
    public RegistrationRequest(String certificatePath, String keyPath, Group group, char[] passphrase, char[] password, char[] confirmation) {
        this.certificatePath = certificatePath; this.keyPath = keyPath; this.group = group;
        this.passphrase = passphrase == null ? new char[0] : passphrase.clone();
        this.password = password == null ? new char[0] : password.clone();
        this.confirmation = confirmation == null ? new char[0] : confirmation.clone();
    }
    @Override public void close() {
        Arrays.fill(passphrase, '\0'); Arrays.fill(password, '\0'); Arrays.fill(confirmation, '\0');
    }
    @Override public String toString() { return "RegistrationRequest[redacted]"; }
}
